/bin/bash -lc "python - <<'PY'
import csv, json, math
from collections import defaultdict, Counter
from pathlib import Path

ROOT = Path('/app')
TOL = 1e-4

def read_csv(path):
    with open(path, newline='') as f:
        return list(csv.DictReader(f))

def num(x):
    return float(x)

def is_intlike(x):
    return abs(x - round(x)) <= 1e-9

config = json.load(open(ROOT/'data/config.json'))
TOL = config['numerical_tolerance']
sites = {r['site_id']:{
    'max_modules': int(r['max_modules']),
    'module_capacity_kgph': num(r['module_capacity_kgph']),
    'min_load_fraction': num(r['min_load_fraction']),
    'module_daily_cost': num(r['module_daily_cost']),
    'variable_cost_per_kg': num(r['variable_cost_per_kg']),
    'tank_base_kg': num(r['tank_base_kg']),
    'tank_module_capacity_kg': num(r['tank_module_capacity_kg']),
    'max_tank_modules': int(r['max_tank_modules']),
    'tank_daily_cost': num(r['tank_daily_cost']),
    'initial_inventory_kg': num(r['initial_inventory_kg']),
    'final_min_inventory_kg': num(r['final_min_inventory_kg']),
    'water_limit_m3_per_day': num(r['water_limit_m3_per_day']),
    'startup_limit': int(r['startup_limit']),
    'polishing_cost_per_kg': num(r['polishing_cost_per_kg']),
    'polishing_daily_cost': num(r['polishing_daily_cost']),
} for r in read_csv(ROOT/'data/sites.csv')}
customers = {r['customer_id']:{
    'purity_required_pct': num(r['purity_required_pct']),
    'service_floor_fraction': num(r['service_floor_fraction']),
    'max_hourly_shortfall_fraction': num(r['max_hourly_shortfall_fraction']),
    'shortfall_cost_per_kg': num(r['shortfall_cost_per_kg']),
} for r in read_csv(ROOT/'data/customers.csv')}
lanes = {r['lane_id']:{
    'origin_site': r['origin_site'],
    'customer_id': r['customer_id'],
    'kg_per_trip': num(r['kg_per_trip']),
    'base_max_trips_per_hour': int(r['base_max_trips_per_hour']),
    'driver_hours_per_trip': num(r['driver_hours_per_trip']),
    'cost_per_trip': num(r['cost_per_trip']),
    'hazmat_window_start': int(r['hazmat_window_start']),
    'hazmat_window_end': int(r['hazmat_window_end']),
} for r in read_csv(ROOT/'data/lanes.csv')}
scenarios = {r['scenario_id']:{
    'probability': num(r['probability']),
    'grid_price_multiplier': num(r['grid_price_multiplier']),
    'emission_cap_kg': num(r['emission_cap_kg']),
    'driver_hours_cap': num(r['driver_hours_cap']),
} for r in read_csv(ROOT/'data/scenarios.csv')}
forecast = {(int(r['hour']), r['site_id']):{
    'renewable_mwh': num(r['renewable_mwh']),
    'grid_price_per_mwh': num(r['grid_price_per_mwh']),
    'grid_emission_kg_per_mwh': num(r['grid_emission_kg_per_mwh']),
} for r in read_csv(ROOT/'data/hourly_forecast.csv')}
scenario_site = {(r['scenario_id'], int(r['hour']), r['site_id']):{
    'renewable_multiplier': num(r['renewable_multiplier']),
    'module_capacity_multiplier': num(r['module_capacity_multiplier']),
    'water_limit_multiplier': num(r['water_limit_multiplier']),
    'grid_cap_mwh': num(r['grid_cap_mwh']),
} for r in read_csv(ROOT/'data/scenario_site_hourly.csv')}
demand = {(r['scenario_id'], int(r['hour']), r['customer_id']): num(r['demand_kg']) for r in read_csv(ROOT/'data/scenario_customer_hourly_demand.csv')}
scenario_lane = {(r['scenario_id'], int(r['hour']), r['lane_id']):{
    'max_trips': num(r['max_trips']),
    'travel_time_multiplier': num(r['travel_time_multiplier']),
    'closed': int(r['closed']),
} for r in read_csv(ROOT/'data/scenario_lane_hourly.csv')}
sol = json.load(open(ROOT/'submissions/solution.json'))

print('scenario_site water multipliers unique sample:', sorted({v['water_limit_multiplier'] for v in scenario_site.values()})[:20], 'count', len({v['water_limit_multiplier'] for v in scenario_site.values()}))
print('module capacity multipliers:', sorted({v['module_capacity_multiplier'] for v in scenario_site.values()}))
print('travel mult values:', sorted({v['travel_time_multiplier'] for v in scenario_lane.values()}))
print('lane max trips values sample:', sorted({v['max_trips'] for v in scenario_lane.values()})[:20])

# coverage and duplicates
families = defaultdict(list)

def add(fam, key, rule, obs, req, repair):
    families[fam].append((key, rule, obs, req, repair))

# infrastructure checks
infra = sol['infrastructure']
seen_sites = Counter()
for i,row in enumerate(infra):
    key=f'infrastructure[{i}]/{row.get(\"site_id\")}'
    for fld in ['site_id','active','electrolyzer_modules','tank_modules','polishing_active']:
        if fld not in row or row[fld] is None:
            add('schema', key, f'missing/non-null field {fld}', row.get(fld), 'present and non-null', 'populate the required field')
    sid=row.get('site_id')
    seen_sites[sid]+=1
    if sid not in sites:
        add('identifier', key, 'site_id must reference sites.csv', sid, 'known site_id', 'use a valid site_id')
        continue
    for fld in ['electrolyzer_modules','tank_modules']:
        if not isinstance(row.get(fld),(int,float)) or not is_intlike(float(row[fld])):
            add('schema', key, f'{fld} must be a whole number', row.get(fld), 'integer', 'round to a valid integer consistent with the plan')
    em=int(round(float(row['electrolyzer_modules']))) if isinstance(row.get('electrolyzer_modules'),(int,float)) else None
    tm=int(round(float(row['tank_modules']))) if isinstance(row.get('tank_modules'),(int,float)) else None
    if em is not None and (em < 0 or em > sites[sid]['max_modules']):
        add('capacity', key, 'selected electrolyzer modules within site max', em, f'0..{sites[sid][\"max_modules\"]}', 'reduce modules or choose a valid site selection')
    if tm is not None and (tm < 0 or tm > sites[sid]['max_tank_modules']):
        add('capacity', key, 'selected tank modules within site max', tm, f'0..{sites[sid][\"max_tank_modules\"]}', 'reduce tank modules to the site limit')
    if row.get('active') is False and ((em or 0)"'!=0 or (tm or 0)!=0 or row.get('"'polishing_active')):
        add('frozen', key, 'inactive sites should not select operating infrastructure', row, 'zero modules and no polishing when inactive', 'set modules/tanks/polishing to zero/false or mark the site active')
for sid in sites:
    if seen_sites[sid]==0:
        add('schema', f'infrastructure/{sid}', 'one infrastructure row for every production site', 0, 1, 'add the missing site row')
    elif seen_sites[sid]>1:
        add('schema', f'infrastructure/{sid}', 'at most one infrastructure row per site', seen_sites[sid], 1, 'deduplicate the repeated site row')

infra_by_site={r['site_id']:r for r in infra if r.get('site_id') in sites}

# operations and shortfalls coverage
ops=sol['operations']
ops_map={}
for i,row in enumerate(ops):
    key=(row.get('scenario_id'), row.get('hour'), row.get('site_id'))
    label=f'operations[{i}]/{key}'
    for fld in ['scenario_id','hour','site_id','online_modules','startup_modules','production_kg','renewable_mwh','grid_mwh','storage_end_kg','vent_kg','water_m3','polishing_kg']:
        if fld not in row or row[fld] is None:
            add('schema', label, f'missing/non-null field {fld}', row.get(fld), 'present and non-null', 'populate the required field')
    if key in ops_map:
        add('schema', label, 'unique operations row per scenario-hour-site', key, 'unique key', 'remove the duplicate key row')
    ops_map[key]=row
    if row.get('scenario_id') not in scenarios:
        add('identifier', label, 'scenario_id must reference scenarios.csv', row.get('scenario_id'), 'known scenario', 'use a valid scenario_id')
    if row.get('site_id') not in sites:
        add('identifier', label, 'site_id must reference sites.csv', row.get('site_id'), 'known site', 'use a valid site_id')
    hour=row.get('hour')
    if not isinstance(hour,(int,float)) or not is_intlike(float(hour)):
        add('schema', label, 'hour must be a whole number', hour, 'integer 0..11', 'replace with an integer hour')
    else:
        hour=int(round(float(hour)))
        if hour < 0 or hour >= config['planning_horizon_hours']:
            add('time', label, 'hour must be within planning horizon', hour, f'0..{config[\"planning_horizon_hours\"]-1}', 'drop or correct the row hour')
    for fld in ['online_modules','startup_modules']:
        val=row.get(fld)
        if not isinstance(val,(int,float)) or not is_intlike(float(val)):
            add('schema', label, f'{fld} must be a whole number', val, 'integer', 'round to a valid integer consistent with state transitions')
    for fld in ['production_kg','renewable_mwh','grid_mwh','storage_end_kg','vent_kg','water_m3','polishing_kg']:
        val=row.get(fld)
        if isinstance(val,(int,float)) and val < -TOL:
            add('schema', label, f'{fld} must be nonnegative', val, '>= 0', 'set the value nonnegative and rebalance the plan')

# required complete ops rows
for sc in scenarios:
  for h in range(config['planning_horizon_hours']):
    for sid in sites:
      if (sc,h,sid) not in ops_map:
        add('schema', f'operations/{sc}/{h}/{sid}', 'one operations row for every scenario-hour-site', 0, 1, 'add the missing operations row')

short=sol['shortfalls']
short_map={}
for i,row in enumerate(short):
    key=(row.get('scenario_id'), row.get('hour'), row.get('customer_id'))
    label=f'shortfalls[{i}]/{key}'
    for fld in ['scenario_id','hour','customer_id','kg']:
        if fld not in row or row[fld] is None:
            add('schema', label, f'missing/non-null field {fld}', row.get(fld), 'present and non-null', 'populate the required field')
    if key in short_map:
        add('schema', label, 'unique shortfall row per scenario-hour-customer', key, 'unique key', 'remove the duplicate key row')
    short_map[key]=row
    if row.get('scenario_id') not in scenarios:
        add('identifier', label, 'scenario_id must reference scenarios.csv', row.get('scenario_id'), 'known scenario', 'use a valid scenario_id')
    if row.get('customer_id') not in customers:
        add('identifier', label, 'customer_id must reference customers.csv', row.get('customer_id'), 'known customer', 'use a valid customer_id')
    hour=row.get('hour')
    if not isinstance(hour,(int,float)) or not is_intlike(float(hour)):
        add('schema', label, 'hour must be a whole number', hour, 'integer 0..11', 'replace with an integer hour')
    elif int(round(float(hour))) not in range(config['planning_horizon_hours']):
        add('time', label, 'hour must be within planning horizon', hour, f'0..{config[\"planning_horizon_hours\"]-1}', 'drop or correct the row hour')
    kg=row.get('kg')
    if isinstance(kg,(int,float)) and kg < -TOL:
        add('schema', label, 'shortfall must be nonnegative', kg, '>= 0', 'set shortfall nonnegative and rebalance deliveries')

for sc in scenarios:
  for h in range(config['planning_horizon_hours']):
    for cid in customers:
      if (sc,h,cid) not in short_map:
        add('schema', f'shortfalls/{sc}/{h}/{cid}', 'one shortfall row for every scenario-hour-customer', 0, 1, 'add the missing shortfall row')

# deliveries schema
ship=sol['deliveries']
ship_by_key=defaultdict(list)
for i,row in enumerate(ship):
    key=(row.get('scenario_id'), row.get('hour'), row.get('lane_id'))
    label=f'deliveries[{i}]/{key}'
    for fld in ['scenario_id','hour','lane_id','kg','trips']:
        if fld not in row or row[fld] is None:
            add('schema', label, f'missing/non-null field {fld}', row.get(fld), 'present and non-null', 'populate the required field')
    if row.get('scenario_id') not in scenarios:
        add('identifier', label, 'scenario_id must reference scenarios.csv', row.get('scenario_id'), 'known scenario', 'use a valid scenario_id')
    if row.get('lane_id') not in lanes:
        add('identifier', label, 'lane_id must reference lanes.csv', row.get('lane_id'), 'known lane', 'use a valid lane_id')
    hour=row.get('hour')
    if not isinstance(hour,(int,float)) or not is_intlike(float(hour)):
        add('schema', label, 'hour must be a whole number', hour, 'integer 0..11', 'replace with an integer hour')
    elif int(round(float(hour))) not in range(config['planning_horizon_hours']):
        add('time', label, 'hour must be within planning horizon', hour, f'0..{config[\"planning_horizon_hours\"]-1}', 'drop or correct the row hour')
    if not isinstance(row.get('trips'),(int,float)) or not is_intlike(float(row['trips'])):
        add('schema', label, 'trips must be a whole number', row.get('trips'), 'integer', 'round to a valid whole-number trip count')
    if isinstance(row.get('kg'),(int,float)) and row['kg'] < -TOL:
        add('schema', label, 'delivered kg must be nonnegative', row['kg'], '>= 0', 'set delivered kg nonnegative and rebalance demand')
    if isinstance(row.get('trips'),(int,float)) and row['trips'] < -TOL:
        add('schema', label, 'trips must be nonnegative', row['trips'], '>= 0', 'set trips nonnegative')
    ship_by_key[key].append(row)

# key coverage duplicate deliveries isn't necessarily invalid; aggregate.

# operational checks
high_purity_customers={cid for cid,c in customers.items() if c['purity_required_pct'] >= 99.9 - 1e-9}
print('Assumed high-purity customers:', sorted(high_purity_customers))

for sc in scenarios:
    emissions=0.0
    driver=defaultdict(float)
    short_by_customer=defaultdict(float)
    demand_by_customer=defaultdict(float)
    water_day=defaultdict(float)
    starts_day=defaultdict(float)
    for h in range(config['planning_horizon_hours']):
        reserve=0.0
        # prepare delivery aggregates this hour
        deliv_from_site=defaultdict(float)
        deliv_to_customer=defaultdict(float)
        trips_lane=defaultdict(float)
        highpur_from_site=defaultdict(float)
        for lane_id, lane in lanes.items():
            rows=ship_by_key.get((sc,h,lane_id),[])
            kg=sum(float(r['kg']) for r in rows)
            trips=sum(float(r['trips']) for r in rows)
            if rows:
                deliv_from_site[lane['origin_site']] += kg
                deliv_to_customer[lane['customer_id']] += kg
                trips_lane[lane_id] += trips
                if lane['customer_id'] in high_purity_customers:
                    highpur_from_site[lane['origin_site']] += kg
        # delivery rules per lane-hour
        for lane_id,lane in lanes.items():
            kg = sum(float(r['kg']) for r in ship_by_key.get((sc,h,lane_id),[]))
            trips = sum(float(r['trips']) for r in ship_by_key.get((sc,h,lane_id),[]))
            scen_lane = scenario_lane[(sc,h,lane_id)]
            if kg > lane['kg_per_trip']*trips + TOL:
                add('capacity', f'deliveries[{sc},{h},{lane_id}]', 'delivered kg cannot exceed submitted trips times payload', kg, f'<= {lane[\"kg_per_trip\"]*trips}', 'increase trips or reduce delivered kg on the lane-hour')
            if trips > scen_lane['max_trips'] + TOL:
                add('time/location', f'deliveries[{sc},{h},{lane_id}]', 'lane-hour trips must respect scenario trip cap', trips, f'<= {scen_lane[\"max_trips\"]}', 'shift or reduce trips on this lane-hour')
            if scen_lane['closed'] and trips > TOL:
                add('time/location', f'deliveries[{sc},{h},{lane_id}]', 'closed lane cannot carry trips', trips, '<= 0', 'set trips and kg to zero or reroute')
            if trips > TOL and not (lane['hazmat_window_start'] <= h <= lane['hazmat_window_end']):
                add('time/location', f'deliveries[{sc},{h},{lane_id}]', 'lane-hour must lie within hazmat window', h, f'{lane[\"hazmat_window_start\"]}..{lane[\"hazmat_window_end\"]}', 'move the delivery into the allowed window')
            driver[h] += trips * lane['driver_hours_per_trip'] * scen_lane['travel_time_multiplier']
        if driver[h] > scenarios[sc]['driver_hours_cap'] + TOL:
            add('time/location', f'scenario={sc},hour={h}', 'total driver hours must respect the scenario cap', driver[h], f'<= {scenarios[sc][\"driver_hours_cap\"]}', 'reduce trips, use shorter lanes, or rebalance by hour')

        for sid,site in sites.items():
            row = ops_map[(sc,h,sid)]
            inf = infra_by_site[sid]
            online = float(row['online_modules'])
            starts = float(row['startup_modules'])
            prod = float(row['production_kg'])
            ren = float(row['renewable_mwh'])
            grid = float(row['grid_mwh'])
            store = float(row['storage_end_kg'])
            vent = float(row['vent_kg'])
            water = float(row['water_m3'])
            polish = float(row['polishing_kg'])
            sel_mod = float(inf['electrolyzer_modules'])
            sel_tanks = float(inf['tank_modules'])
            capmult = scenario_site[(sc,h,sid)]['module_capacity_multiplier']
            ren_cap = forecast[(h,sid)]['renewable_mwh'] * scenario_site[(sc,h,sid)]['renewable_multiplier']
            grid_cap = scenario_site[(sc,h,sid)]['grid_cap_mwh']
            storage_cap = site['tank_base_kg'] + sel_tanks * site['tank_module_capacity_kg']
            min_prod = online * site['module_capacity_kgph'] * site['min_load_fraction'] * capmult
            max_prod = online * site['module_capacity_kgph'] * capmult
            reserve += store
            emissions += grid * forecast[(h,sid)]['grid_emission_kg_per_mwh']
            water_day[sid] += water
            starts_day[sid] += starts
            if online > sel_mod + TOL:
                add('frozen', f'operations[{sc},{h},{sid}]', 'online modules cannot exceed selected first-stage modules', online, f'<= {sel_mod}', 'lower online modules or increase the infrastructure selection')
            if starts > online + TOL:
                add('setup', f'operations[{sc},{h},{sid}]', 'startup modules in an hour cannot exceed online modules in that hour', starts, f'<= {online}', 'reduce startup count to the actual modules brought online')
            prev_online = 0.0 if h == 0 else float(ops_map[(sc,h-1,sid)]['online_modules'])
            needed_starts = max(0.0, online - prev_online)
            if starts + TOL < needed_starts:
                add('setup', f'operations[{sc},{h},{sid}]', 'startup modules must cover increases in online modules', starts, f'>= {needed_starts}', 'raise startup_modules or lower the online jump')
            if online < -TOL:
                add('capacity', f'operations[{sc},{h},{sid}]', 'online modules must be nonnegative', online, '>= 0', 'set online_modules nonnegative')
            if prod > max_prod + TOL:
                add('capacity', f'operations[{sc},{h},{sid}]', 'production cannot exceed scenario-adjusted online-module capacity', prod, f'<= {max_prod}', 'reduce production or increase valid online capacity')
            if online > TOL and prod + TOL < min_prod:
                add('capacity', f'operations[{sc},{h},{sid}]', 'production must respect minimum load when modules are online', prod, f'>= {min_prod}', 'either shut modules down or raise production to minimum load')
            if ren > ren_cap + TOL:
                add('capacity', f'operations[{sc},{h},{sid}]', 'renewable use cannot exceed scenario-adjusted availability', ren, f'<= {ren_cap}', 'reduce renewable_mwh to the available forecast')
            if grid > grid_cap + TOL:
                add('capacity', f'operations[{sc},{h},{sid}]', 'grid use cannot exceed scenario site-hour cap', grid, f'<= {grid_cap}', 'reduce grid_mwh or shift production')
            req_energy = prod*config['energy_mwh_per_kg_h2'] + polish*config['polishing_mwh_per_kg']
            if ren + grid + TOL < req_energy:
                add('capacity', f'operations[{sc},{h},{sid}]', 'energy inputs must cover production plus polishing load', ren+grid, f'>= {req_energy}', 'increase renewable/grid use or reduce production/polishing')
            req_water = prod*config['water_m3_per_kg_h2']
            if abs(water-req_water) > 5e-4:
                add('conservation', f'operations[{sc},{h},{sid}]', 'water must match production using the public conversion factor', water, f'{req_water}', 'set water_m3 = production_kg * 0.0105')
            prev_store = site['initial_inventory_kg'] if h == 0 else float(ops_map[(sc,h-1,sid)]['storage_end_kg'])
            rhs = prev_store + prod - deliv_from_site[sid] - vent
            if abs(store-rhs) > 5e-4:
                add('conservation', f'operations[{sc},{h},{sid}]', 'storage_end must equal prior inventory plus production minus outbound deliveries and venting', store, f'{rhs}', 'rebalance storage_end, production, venting, or outbound deliveries')
            if store > storage_cap + TOL:
                add('conservation', f'operations[{sc},{h},{sid}]', 'site inventory cannot exceed selected storage capacity', store, f'<= {storage_cap}', 'add tank modules, lower inventory, or increase outbound flow')
            if store < -TOL:
                add('conservation', f'operations[{sc},{h},{sid}]', 'site inventory must stay nonnegative', store, '>= 0', 'reduce outbound flow or increase production')
            if h == config['planning_horizon_hours']-1 and store + TOL < site['final_min_inventory_kg']:
                add('conservation', f'operations[{sc},{h},{sid}]', 'final inventory must meet the site minimum', store, f'>= {site[\"final_min_inventory_kg\"]}', 'retain more inventory by the end of the day')
            if polish > TOL and not inf['polishing_active']:
                add('time/location', f'operations[{sc},{h},{sid}]', 'polishing_kg can be positive only at sites with polishing active', polish, '= 0 when polishing_active is false', 'turn on polishing in infrastructure or set polishing_kg to zero')
            if highpur_from_site[sid] > polish + TOL:
                add('time/location', f'operations[{sc},{h},{sid}]', 'high-purity deliveries from a site-hour cannot exceed polished hydrogen that hour', highpur_from_site[sid], f'<= {polish}', 'increase polishing_kg at a polishing-capable site or reduce high-purity deliveries')
        if reserve + TOL < config['system_min_reserve_kg']:
            add('reserve', f'scenario={sc},hour={h}', 'system reserve at hour end must meet the network minimum', reserve, f'>= {config[\"system_min_reserve_kg\"]}', 'retain more inventory across the network by hour end')

        for cid,c in customers.items():
            sh = float(short_map[(sc,h,cid)]['kg'])
            dem = demand[(sc,h,cid)]
            delivered = deliv_to_customer[cid]
            demand_by_customer[cid] += dem
            short_by_customer[cid] += sh
            if abs(delivered + sh - dem) > 5e-4:
                add('conservation', f'demand[{sc},{h},{cid}]', 'each customer-hour demand must equal deliveries plus shortfall', delivered + sh, f'{dem}', 'rebalance deliveries and shortfall to exactly match demand')
            max_short = c['max_hourly_shortfall_fraction'] * dem
            if sh > max_short + TOL:
                add('reserve', f'shortfalls[{sc},{h},{cid}]', 'hourly shortfall cannot exceed the customer cap', sh, f'<= {max_short}', 'deliver more in that hour or revise the shortfall allocation')
    for sid,site in sites.items():
        # possible interpretations of water stress: daily sum <= minimum hourly multiplier * daily cap or maybe every-hour multiplier aggregated. compute against min and avg diagnostic.
        wm = [scenario_site[(sc,h,sid)]['water_limit_multiplier'] for h in range(config['planning_horizon_hours'])]
        daily_cap_min = site['water_limit_m3_per_day'] * min(wm)
        daily_cap_avg = site['water_limit_m3_per_day'] * sum(wm)/len(wm)
        if water_day[sid] > daily_cap_min + TOL:
            add('capacity', f'scenario={sc},site={sid}', 'daily water use cannot exceed the scenario-adjusted site permit under the conservative public interpretation', water_day[sid], f'<= {daily_cap_min}', 'reduce production or choose a looser interpretation backed by the prompt')
        if starts_day[sid] > site['startup_limit'] + TOL:
            add('setup', f'scenario={sc},site={sid}', 'daily startup modules cannot exceed the site startup limit', starts_day[sid], f'<= {site[\"startup_limit\"]}', 'reduce online restarts over the day')
    if emissions > scenarios[sc]['emission_cap_kg'] + TOL:
        add('capacity', f'scenario={sc}', 'scenario grid emissions must respect the scenario cap', emissions, f'<= {scenarios[sc][\"emission_cap_kg\"]}', 'cut grid use or shift production to lower-emission hours/sites')
    for cid,c in customers.items():
        min_service = c['service_floor_fraction'] * demand_by_customer[cid]
        delivered_total = demand_by_customer[cid] - short_by_customer[cid]
        if delivered_total + TOL < min_service:
